    private record UserProfilePayload(
        string? UserId,
        string? Role,
        string? BusinessOrOrgName,
        string? Address,
        string? BioOrDescription,
        string? DonorType,
        string? ProfilePictureUrl,
        List<string>? AcceptedFoodCategories
    );

    private async Task<UserProfilePayload?> FetchUserProfileFromUserServiceAsync(string userId)
    {
        try
        {
            var client = _httpClientFactory.CreateClient();
            client.Timeout = TimeSpan.FromSeconds(3);
            var baseUrl = _configuration["UserService:BaseUrl"] ?? "http://localhost:5000";
            var response = await client.GetAsync($"{baseUrl.TrimEnd('/')}/api/profile/{userId}");
            if (response.IsSuccessStatusCode)
            {
                var content = await response.Content.ReadAsStringAsync();
                using var doc = JsonDocument.Parse(content);
                if (doc.RootElement.TryGetProperty("data", out var dataEl))
                {
                    var accepted = new List<string>();
                    if (dataEl.TryGetProperty("acceptedFoodCategories", out var ac) && ac.ValueKind == JsonValueKind.Array)
                    {
                        foreach (var item in ac.EnumerateArray())
                        {
                            var s = item.GetString();
                            if (!string.IsNullOrWhiteSpace(s)) accepted.Add(s);
                        }
                    }

                    return new UserProfilePayload(
                        dataEl.TryGetProperty("userId", out var u) ? u.GetString() : null,
                        dataEl.TryGetProperty("role", out var r) ? r.GetString() : null,
                        dataEl.TryGetProperty("businessOrOrgName", out var b) ? b.GetString() : null,
                        dataEl.TryGetProperty("address", out var a) ? a.GetString() : null,
                        dataEl.TryGetProperty("bioOrDescription", out var bd) ? bd.GetString() : null,
                        dataEl.TryGetProperty("donorType", out var dt) ? dt.GetString() : null,
                        dataEl.TryGetProperty("profilePictureUrl", out var p) ? p.GetString() : null,
                        accepted
                    );
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogDebug(ex, "Could not fetch user profile from UserService for {UserId}", userId);
        }
        return null;
    }

    public async Task<ApiResponse<DonationResponseDto>> DeductQuantityAsync(int id, int quantity)
    {
        try
        {
            if (quantity <= 0)
            {
                return ApiResponse<DonationResponseDto>.Fail("Deduction quantity must be greater than 0.");
            }

            var donation = await _context.Donations.FindAsync(id);
            if (donation == null)
            {
                return ApiResponse<DonationResponseDto>.Fail($"Donation with ID {id} not found.");
            }

            if (donation.Status == "Cancelled" || donation.Status == "Expired" || donation.Status == "FullyClaimed")
            {
                return ApiResponse<DonationResponseDto>.Fail($"Donation {id} is currently {donation.Status} and cannot be requested/claimed.");
            }

            if (DateTime.UtcNow > donation.ExpiryTime)
            {
                donation.Status = "Expired";
                await _context.SaveChangesAsync();
                return ApiResponse<DonationResponseDto>.Fail($"Donation {id} has expired.");
            }

            if (donation.RemainingQuantity < quantity)
            {
                return ApiResponse<DonationResponseDto>.Fail($"Insufficient remaining quantity. Requested: {quantity}, Available: {donation.RemainingQuantity}.");
            }

            donation.ClaimedQuantity += quantity;
            donation.RemainingQuantity -= quantity;

            if (donation.RemainingQuantity <= 0)
            {
                donation.RemainingQuantity = 0;
                donation.Status = "FullyClaimed";
            }
            else
            {
                donation.Status = "PartiallyClaimed";
            }

            donation.UpdatedAt = DateTime.UtcNow;
            await _context.SaveChangesAsync();

            _logger.LogInformation("Successfully deducted {Quantity} from Donation {DonationId}. Remaining: {Remaining}, Status: {Status}",
                quantity, id, donation.RemainingQuantity, donation.Status);

            return ApiResponse<DonationResponseDto>.Ok(MapToResponseDto(donation), "Donation quantity updated successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error deducting quantity from Donation {DonationId}", id);
            return ApiResponse<DonationResponseDto>.Fail($"Internal server error: {ex.Message}");
        }
    }

    public async Task<ApiResponse<object>> GetAdminDonationSummaryAsync()
    {
        try
        {
            var allDonations = await _context.Donations.ToListAsync();
            var totalCount = allDonations.Count;
            var availableCount = allDonations.Count(d => d.Status == "Available" || d.Status == "Posted");
            var claimedCount = allDonations.Count(d => d.Status == "FullyClaimed" || d.Status == "PartiallyClaimed" || d.Status == "Completed");
            var expiredCount = allDonations.Count(d => d.Status == "Expired" || (d.Status != "Completed" && d.Status != "Cancelled" && DateTime.UtcNow > d.ExpiryTime));
            var cancelledCount = allDonations.Count(d => d.Status == "Cancelled");

            var totalPortionsRescued = allDonations.Sum(d => d.ClaimedQuantity);
            var totalPortionsListed = allDonations.Sum(d => d.TotalQuantity);

            var summary = new
            {
                totalCount,
                availableCount,
                claimedCount,
                expiredCount,
                cancelledCount,
                totalPortionsRescued,
                totalPortionsListed,
                recentDonations = allDonations.OrderByDescending(d => d.CreatedAt).Take(10).Select(MapToResponseDto)
            };

            return ApiResponse<object>.Ok(summary, "Admin donation monitoring summary retrieved.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error generating admin donation monitoring summary.");
            return ApiResponse<object>.Fail($"Failed to generate donation summary: {ex.Message}");
        }
    }

    private static DonationResponseDto MapToResponseDto(Donation d)
    {
        var effectiveStatus = d.Status;

        if (effectiveStatus != "Completed" && effectiveStatus != "Cancelled")
        {
            if (DateTime.UtcNow > d.ExpiryTime)
            {
                effectiveStatus = "Expired";
            }
            else if (string.IsNullOrWhiteSpace(effectiveStatus) || effectiveStatus == "Posted")
            {
                effectiveStatus = d.RemainingQuantity <= 0 ? "FullyClaimed" : (d.ClaimedQuantity > 0 ? "PartiallyClaimed" : "Available");
            }
        }

        var calculatedRemaining = effectiveStatus == "Cancelled" ? 0 : (d.RemainingQuantity <= 0 && d.ClaimedQuantity == 0 ? d.TotalQuantity : d.RemainingQuantity);

        return new DonationResponseDto
        {
            Id = d.Id,
            DonorId = d.DonorId,
            DonorName = d.DonorName,
            DonorEmail = d.DonorEmail,
            FoodTitle = d.FoodTitle,
            Category = d.Category,
            TotalQuantity = d.TotalQuantity,
            ClaimedQuantity = d.ClaimedQuantity,
            RemainingQuantity = calculatedRemaining,
            Unit = d.Unit,
            ExpiryTime = d.ExpiryTime,
            CollectionMode = d.CollectionMode,
            Status = effectiveStatus,
            Location = d.Location,
            Notes = d.Notes,
            DietaryTags = d.DietaryTags,
            CreatedAt = d.CreatedAt
        };
    }
